float hash21(float2 p)
{
    p = frac(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return frac(p.x * p.y);
}

float vnoise(float2 p)
{
    float2 c = floor(p);
    float2 f = frac(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(c);
    float b = hash21(c + float2(1.0, 0.0));
    float d = hash21(c + float2(0.0, 1.0));
    float e = hash21(c + float2(1.0, 1.0));
    return lerp(lerp(a, b, u.x), lerp(d, e, u.x), u.y);
}

float fbm(float2 p)
{
    float v = 0.0;
    float a = 0.5;
    for (int k = 0; k < 4; k++) { v += a * vnoise(p); p = p * 2.03 + float2(1.7, 9.2); a *= 0.5; }
    return v;
}

float2 arcRS(float2 uv)
{
    float2 p = uv - 0.5;
    float r = length(p) * 2.0;
    float th = atan2(p.y, p.x) * 57.29578;
    th = th + step(th, -90.0) * 360.0;
    return float2(r, (165.0 - th) / 150.0);
}

float arcProfile(float sc)
{
    return pow(sc, 0.9) * (1.0 - smoothstep(0.86, 1.0, sc));
}

code.fragment:
float4 frag(UPEInput i)
{
    float life = 1.0 - i.color.a;
    float2 a = arcRS(i.uv);
    float r = a.x;
    float s = a.y;
    float sc = saturate(s);
    float inArc = step(0.0, s) * step(s, 1.0);
    float R0 = 0.94;
    float prof = arcProfile(sc);
    float w = _Width * prof;

    // yay boyunca akan lifler (başa doğru)
    float flow = s * 3.0 - i.time * _Scroll;
    float f1 = fbm(float2(r * _Fiber, flow));
    float f2 = vnoise(float2(r * _Fiber * 2.6 + 4.0, flow * 2.3));
    float fib = saturate(f1 * 0.8 + f2 * 0.45);
    float clump = vnoise(float2(s * 9.0 - i.time * _Scroll * 0.5, 7.0));

    float innerR = R0 - w * (0.7 + (f1 - 0.5) * 0.9 + (clump - 0.5) * 0.5);
    float band = smoothstep(innerR - 0.004, innerR + 0.04, r) * (1.0 - smoothstep(R0 - 0.003, R0 + 0.006, r));
    float d = saturate((r - innerR) / max(R0 - innerR, 0.001)); // 0 iç → 1 dış

    float rev = saturate(life / _Reveal);
    float revealM = 1.0 - smoothstep(rev * 1.04 - 0.06, rev * 1.04, s);
    float e = saturate((life - _ErodeStart) / max(1.0 - _ErodeStart, 0.001));
    float er = fbm(float2(s * 7.0 - i.time * 1.5, r * 9.0));
    float erodeM = saturate((er + 0.5 - e * 1.35 - (1.0 - sc) * e * 0.6) * 6.0);
    float headHot = 1.0 + 1.2 * (1.0 - smoothstep(0.0, 0.2, rev * 1.04 - s)) * (1.0 - e);

    // renk: iç mor → mavi → camgöbeği → beyaz dış kenar
    float3 col = lerp(_ColC.rgb, _ColB.rgb, smoothstep(0.0, 0.45, d));
    col = lerp(col, _ColA.rgb, smoothstep(0.45, 0.85, d));
    col *= 0.35 + 1.1 * fib;
    float cw = max(_CoreW * (0.4 + prof), 0.001);
    float core = (1.0 - smoothstep(0.0, cw, abs(R0 - cw * 0.6 - r))) * step(0.001, w) * smoothstep(0.0, 0.1, sc) * (1.0 - e * 0.7);
    float body = band * (0.3 + 0.7 * d) * (0.35 + 0.65 * fib) * 1.8;
    float m = inArc * revealM * erodeM * headHot * _Gain;
    col = (col * body + _Core.rgb * core) * m * i.color.rgb;
    return float4(col, 1.0);
}
